@startuml

class Airline {
  + ID
}

class Flight {
  + ID
  + departure_time
  + arrival_time
}

class Airport {
  + ID
}

class Aircraft {
  + name
  + repair
  + landed
}

class AircraftType {
  + name
}

class Pilot {
  + experience_level
}

Airline "1" -- "*" Flight : operates
Flight "*" -- "1" Airport : departs from
Flight "*" -- "1" Airport : arrives to
Flight "*" -- "1" Pilot : captain
Flight "*" -- "1" Pilot : co-pilot
Flight "*" -- "1" Aircraft : uses
Airline "1" -- "*" Aircraft : owns
Aircraft "*" -- "1" AircraftType : is of
AircraftType "1" -- "1..*" Pilot : captain
AircraftType "1" -- "1..*" Pilot : co-pilot
AircraftType "1" -- "0..*" Pilot : navigator

@enduml

